package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string = ""

var SchedRecVar SchedRec

var schedFile *os.File
var schedReader *bufio.Reader

func formatZZZZZZZZ9_99(v decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99  len 13  int digits 8, dec 2
	// truncate toward zero to 2 decimals then format
	// v is already rounded/truncated to 2 decimals
	negative := v.Sign() < 0
	if negative {
		v = v.Neg()
	}
	v = v.Truncate(2)
	// separate int and frac
	// Use string to avoid float
	// v.StringFixed(2) gives exactly 2 decimal places
	s := v.StringFixed(2) // e.g. "1234.56"
	parts := strings.Split(s, ".")
	intPartStr := parts[0]
	fracPartStr := "00"
	if len(parts) > 1 {
		fracPartStr = parts[1]
		if len(fracPartStr) < 2 {
			fracPartStr = fracPartStr + strings.Repeat("0", 2-len(fracPartStr))
		} else if len(fracPartStr) > 2 {
			fracPartStr = fracPartStr[:2]
		}
	}
	// high-order truncation to 8 integer digits: keep low-order digits
	if len(intPartStr) > 8 {
		intPartStr = intPartStr[len(intPartStr)-8:]
	}
	// pad to 8 digits with leading zeros
	intPartStr = strings.Repeat("0", 8-len(intPartStr)) + intPartStr

	// picture integer part characters: "ZZ,ZZZ,ZZ9" -> 10 chars including commas
	// map positions to digit index
	picInt := []rune("ZZ,ZZZ,ZZ9") // 10
	digitIdx := 0
	// intPartStr has 8 digits, pic has 8 digit placeholders (Z or 9)
	// they align: number of digit placeholders = 8
	// commas are literal
	// Build int formatted
	intRunes := make([]rune, len(picInt))
	di := 0
	for i, ch := range picInt {
		if ch == 'Z' || ch == '9' {
			intRunes[i] = rune(intPartStr[di])
			di++
		} else {
			intRunes[i] = ch // ',' 
		}
	}
	// Z suppression: replace leading Z positions with space, and commas in suppressed zone with space
	// Find last leading zero that should be suppressed
	// All Z positions that are before the last non-zero digit among Z positions, plus commas between
	// COBOL rule: suppress leading zeros for Z, and commas inside suppressed zone become spaces
	// Implementation: scan digit placeholders left to right, determine if still in leading zero suppression
	suppressing := true
	// Need to know index of last Z zero that is leading
	// We suppress a Z '0' if all digit positions (including following 9's?) to the left? Actually 9 always prints.
	// Simpler: suppression continues while every digit placeholder examined so far (and all remaining?) is zero?
	// Standard: Z suppression stops at last non-zero digit before the decimal; zeros after that (even in Z positions) print as '0'.
	// So find position of last non-zero digit among all digit placeholders.
	lastNonZero := -1
	for i, ch := range picInt {
		if ch == 'Z' || ch == '9' {
			// digit char at this i is intRunes[i]
			if intRunes[i] != '0' {
				lastNonZero = i
			}
		}
	}
	// If all zeros, we should print single zero at the mandatory 9 position
	// So suppression applies to all Z positions with index < position of the 9? But if lastNonZero == -1, we suppress all Z.
	for i, ch := range picInt {
		if ch == 'Z' {
			if suppressing {
				// if this Z is before or at the lastNonZero, need to decide
				// If lastNonZero == -1 -> suppress all Z
				// else if i < lastNonZero -> this Z is leading, but if its digit is zero and all earlier non-zero? Actually if there is a non-zero after, we may need to show zeros between.
				// Correct rule: once we hit lastNonZero, suppression ends. But zeros between leading and lastNonZero should be '0', not space.
				// So suppress only while we haven't yet encountered a non-zero and this position is still before lastNonZero and digit is '0'
				// Equivalent: if i < lastNonZero, then digit should be shown as '0' if we have already passed a non-zero? But we track.
				if lastNonZero == -1 {
					intRunes[i] = ' '
				} else {
					if i < lastNonZero {
						// check if there was any non-zero before or at i
						// if digit is '0' and no non-zero yet encountered, suppress
						hasNonZeroBefore := false
						for k := 0; k <= i; k++ {
							if (picInt[k] == 'Z' || picInt[k] == '9') && intRunes[k] != '0' && intRunes[k] != ' ' {
								// but intRunes may already be space? use original digit
							}
						}
						// Simpler: if i is before lastNonZero and we are still suppressing and digit is '0', keep suppressing; if digit is non-zero, stop suppressing
						if intRunes[i] == '0' {
							// check if there is any non-zero at or before i
							found := false
							for k := 0; k <= i; k++ {
								if (picInt[k] == 'Z' || picInt[k] == '9') {
									origDigit := rune(intPartStr[digitIndexForPicPos(picInt, k)])
									if origDigit != '0' {
										found = true
										break
									}
								}
							}
							if !found {
								intRunes[i] = ' '
							} else {
								suppressing = false
							}
						} else {
							suppressing = false
						}
					} else {
						// i >= lastNonZero but this is Z and lastNonZero is before, shouldn't happen because lastNonZero is the last non-zero, so any Z after it would be zero but should show 0
						// Actually if lastNonZero is before this Z, then this Z digit is zero and is after last non-zero -> should show '0'
						suppressing = false
					}
				}
			}
		} else if ch == ',' {
			if suppressing {
				// comma is suppressed if all digit placeholders to its left are suppressed (i.e., are spaces)
				// Check if any non-space digit before it
				anyVisible := false
				for k := 0; k < i; k++ {
					if (picInt[k] == 'Z' || picInt[k] == '9') && intRunes[k] != ' ' {
						anyVisible = true
						break
					}
				}
				// Also if all remaining digits are zero, comma suppressed
				// Determine if still suppressing: if no visible digit yet, comma becomes space
				if !anyVisible {
					intRunes[i] = ' '
				}
			}
			// if not suppressing, comma stays
		} else if ch == '9' {
			// always digit, but check suppressing ends
			suppressing = false
		}
	}
	intStr := string(intRunes)
	result := intStr + "." + fracPartStr
	if negative {
		// not needed for this program, but handle
		result = "-" + result
	}
	return result
}

func digitIndexForPicPos(pic []rune, pos int) int {
	idx := 0
	for i := 0; i < pos; i++ {
		if pic[i] == 'Z' || pic[i] == '9' {
			idx++
		}
	}
	return idx
}

func formatPIC99(v int64) string {
	s := fmt.Sprintf("%02d", v)
	if len(s) > 2 {
		s = s[len(s)-2:]
	}
	return s
}

func main() {
	var err error
	schedFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer schedFile.Close()
	schedReader = bufio.NewReader(schedFile)

	WsEofFlag = "N"
	WsBal = decimal.NewFromInt(0)
	WsYear = 0
	WsCount = 0

	MAIN_PARA()
}

func MAIN_PARA() {
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	// DISPLAY "SCHEDULES: " WS-COUNT
	fmt.Printf("SCHEDULES: %s\n", formatPIC99(WsCount))
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func READ_PARA() {
	line, err := schedReader.ReadString('\n')
	if err != nil && len(line) == 0 {
		WsEofFlag = "Y"
		return
	}
	// Remove trailing newline \n and \r
	line = strings.TrimRight(line, "\r\n")
	if err != nil && len(line) == 0 {
		// EOF with no data
		WsEofFlag = "Y"
		return
	}
	// Check for EOF case where ReadString returned EOF but line has content (last line without newline)
	// In that case next read will be EOF
	// Pad to 16
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	} else if len(line) > 16 {
		line = line[:16]
	}
	// If line was empty due to EOF, handle
	if err != nil {
		// we have a record, but next read will be EOF; still process this record
		// So don't set done yet; but need to handle properly: if line is all spaces and err==EOF, it's still a record
		// To detect true EOF, the next call will get err
		// So we parse this record
	}

	// Parse fields
	rawAcct := line[0:4]
	rawPrin := line[4:11]
	rawRate := line[11:15]
	rawYears := line[15:16]

	SchedRecVar.ScAcct = rawAcct

	// SC-PRIN 9(5)V99 len 7 digits
	{
		s := strings.TrimSpace(rawPrin)
		if s == "" {
			s = "0"
		}
		// keep only digits, pad
		digits := ""
		for _, c := range s {
			if c >= '0' && c <= '9' {
				digits += string(c)
			}
		}
		if digits == "" {
			digits = "0"
		}
		d, _ := decimal.NewFromString(digits)
		SchedRecVar.ScPrin = decimal.NewFromBigInt(d.BigInt(), -2)
	}
	{
		s := strings.TrimSpace(rawRate)
		if s == "" {
			s = "0"
		}
		digits := ""
		for _, c := range s {
			if c >= '0' && c <= '9' {
				digits += string(c)
			}
		}
		if digits == "" {
			digits = "0"
		}
		d, _ := decimal.NewFromString(digits)
		SchedRecVar.ScRate = decimal.NewFromBigInt(d.BigInt(), -2)
	}
	{
		s := strings.TrimSpace(rawYears)
		if s == "" {
			SchedRecVar.ScYears = 0
		} else {
			var v int64
			fmt.Sscan(s, &v)
			SchedRecVar.ScYears = v
		}
	}

	// Peek for EOF: if underlying err was EOF, next call will handle; but we need to detect that file ended after this line
	// We set EOF flag only on next read when ReadString fails with no data.
	// So if this call had err==io.EOF, we have consumed last line; next call will set done. To avoid extra iteration, we don't set done now.
	// However if file had no more data, the current line is valid; keep flag N.
	// To know, check if err != nil and we are at EOF, we will still have WsEofFlag=N.
	// Next READ_PARA will set Y.
	if strings.TrimSpace(line) == "" && len(line) == 16 {
		// could be padded blank line at EOF; treat as EOF if we already hit err
		// But keep as is
	}
	// If line was actually incomplete due to EOF with no bytes, handled at top
	if err != nil {
		// Mark that next read should be EOF; we implement by checking if underlying file has no more data
		// Set a flag to indicate next read is EOF by peeking
		// Simplest: if err != nil, we have just read last line; we keep WsEofFlag=N for now
		// The next READ_PARA will return EOF
		// No action
		_ = err
	}
	// Detect true EOF on next call: we need to know when ReadString returns error and len==0
	// Our top check handles it
}

func PROCESS_PARA() {
	// MOVE SC-PRIN TO WS-BAL (with truncation to 9(8)V99)
	WsBal = SchedRecVar.ScPrin.Truncate(2)
	// Keep low-order digits if overflow (not needed)
	for WsYear = 1; WsYear <= SchedRecVar.ScYears; WsYear++ {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		rateDiv := SchedRecVar.ScRate.Shift(-2) // /100
		one := decimal.NewFromInt(1)
		factor := one.Add(rateDiv)
		WsBal = WsBal.Mul(factor).Round(2)
		// handle overflow truncation high-order digits (PIC 9(8)V99)
		WsBal = truncateToPic9_8V99(WsBal)
		WsBalEd = formatZZZZZZZZ9_99(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		fmt.Printf("%s Y%s %s\n", SchedRecVar.ScAcct, formatPIC99(WsYear), WsBalEd)
	}
	WsBalEd = formatZZZZZZZZ9_99(WsBal)
	fmt.Printf("%s FINAL %s\n", SchedRecVar.ScAcct, WsBalEd)
	WsCount = WsCount + 1
	READ_PARA()
}

func truncateToPic9_8V99(v decimal.Decimal) decimal.Decimal {
	// keep only low-order digits that fit in 9(8)V99, truncated to 2 decimals
	v = v.Truncate(2)
	neg := v.Sign() < 0
	if neg {
		v = v.Neg()
	}
	// mod 10^8 for integer part
	// total = intPart*100 + frac
	// Compute integer keeping mod
	s := v.StringFixed(2)
	parts := strings.Split(s, ".")
	intStr := parts[0]
	if len(intStr) > 8 {
		intStr = intStr[len(intStr)-8:]
	}
	newStr := intStr + "." + parts[1]
	d, _ := decimal.NewFromString(newStr)
	if neg {
		d = d.Neg()
	}
	return d
}

